// CSD_RATIONALE_BEGIN
// Root-cause analysis of attempt 72 (53.3%):
//
// 1. GUIDANCE MISMATCH: The guidance was output-format focused ("use exact table and
//    column names from the provided schema") rather than question-mapping focused.
//    This did not prevent the model from adding unrequested columns (example 1:
//    adds `name` to `SELECT age, hometown`), using wrong aggregation structure
//    (example 2: wrong COUNT logic), or generating repetitive WHERE clauses
//    (example 3: 24 repeated `AND countrycode = (...)` blocks).
//
// 2. PREAMBLE INTERFERENCE: The 5-step unconstrained preamble let the model begin
//    emitting SQL tokens ("SELECT", ...) BEFORE `<<` was forced. After those tokens,
//    `OpenConstrainedSpan` inserted `<<` mid-sequence, so the constrained grammar
//    restarted with currentConstrained=[] while the generated prefix already
//    contained partial SQL. This likely confused the LM about its own output state.
//
// 3. OVER-GENEROUS BUDGET: budget=400 gave room for long repetitive SQL extensions.
//    Spider queries rarely need more than ~80 constrained tokens.
//
// Fixes in this attempt:
//
// A. GUIDANCE OVERHAUL: Replace format-guidance with semantic-precision rules
//    directly targeting the three observed failure types:
//    - "SELECT only columns explicitly asked about" → fixes extra-column errors
//    - "COUNT for 'how many'" → fixes aggregation structure errors
//    - "INTERSECT for both X and Y" → fixes dual-condition queries
//    - "Generate shortest query" → discourages repetitive extensions
//
// B. ELIMINATE PREAMBLE: Skip all unconstrained steps; call OpenConstrainedSpan
//    immediately. The constrained grammar starts fresh with currentConstrained=[],
//    and the LM has no prior unconstrained SQL tokens to "continue" from.
//
// C. SHORTER BUDGET: 250 instead of 400. Adequate for complex Spider SQL
//    (WHERE/JOIN/GROUP BY/ORDER BY), but limits repetition room.
//
// Structure: OpenConstrainedSpan (1 step) + CloseSpanWithinBudget (≤250 steps).
// Total cost ≤ 251 << 900 budget.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// OpenConstrainedSpan branch (Phase 1): Runs only when !insideConstrainedOut.
//   Its postcondition sets insideConstrainedOut := true and
//   currentConstrainedOut := []. IsValidPrefix([]) holds by method precondition
//   (parser.IsValidPrefix([]) is a stated require). After this point the
//   invariant holds: true ==> IsValidPrefix([]).
//
// CloseSpanWithinBudget branch (Phase 2): Directly postconditioned with
//   (!insideConstrainedOut ==> currentConstrainedOut == []) and
//   (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)).
//   Both the closed-span and open-span paths from CloseSpanWithinBudget
//   satisfy the invariant unconditionally.
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1 (OpenConstrainedSpan): appends exactly 1 "<<" token, steps := 1.
//   |generated| = |generatedPrefix| + 1 = |generatedPrefix| + steps. ✓
//
// Phase 2 (CloseSpanWithinBudget): postcondition gives |generatedOut| <=
//   |generated_before_phase2| + closeBudget. We set steps += closeBudget.
//   So |generated_final| <= |generatedPrefix| + 1 + closeBudget =
//   |generatedPrefix| + steps_final. Tokens consumed by dead-end avoidance,
//   EOS detection, or rejected suffixes inside CloseSpanWithinBudget count
//   against closeBudget but are not appended visibly; visible growth is still
//   bounded by closeBudget as required. ✓
//
// Precondition |currentConstrainedOut| <= |generated| for CloseSpanWithinBudget:
//   If Phase 1 ran: currentConstrainedOut := [], |generated| >= 1. Holds trivially.
//   If Phase 1 skipped (insideConstrained true on entry): method precondition
//   requires |currentConstrained| <= |generatedPrefix| = |generated|. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Text-to-SQL translation. Generate a minimal correct SQL SELECT query. CRITICAL RULES: (1) SELECT clause must contain ONLY the exact columns explicitly requested in the question - do not add extra columns not mentioned. (2) For 'how many' questions use COUNT. (3) For unique or different values use DISTINCT or COUNT(DISTINCT col). (4) Translate every constraint in the question to a WHERE or HAVING condition. (5) For 'both X and Y' conditions that apply independently use INTERSECT. (6) Generate the shortest query that completely answers the question.");

var steps: nat := 0;

// Phase 1: Force open constrained span immediately — no unconstrained preamble.
// Skipping the preamble prevents the model from emitting SQL tokens before "<<"
// and avoids the confusion of a restarted grammar inside a partial SQL context.
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 2: Generate full constrained SQL and close at the longest valid complete
// prefix within the budget. Budget=250 covers complex Spider SQL (including
// WHERE/JOIN/GROUP BY/ORDER BY/HAVING) while limiting room for repetitive loops.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 250 {
    closeBudget := remaining;
  } else {
    closeBudget := 250;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

